53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
112	        rejectCityAtCapacity(owner.getCity());
113	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
114	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
115	        }
116	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
117	        rejectDuplicateTelephone(telephone);
118	        owner.setTelephone(telephone);
119	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
120	        if (owner.getRegistrationDate() == null) {
121	            owner.setRegistrationDate(java.time.LocalDate.now());
122	        }
123	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
124	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    /**
133	     * The maximum number of owners a single city may contain. Creating an owner in a city that
134	     * already holds this many owners is rejected.
135	     */
136	    private static final int CITY_CAPACITY = 50;
137	
138	    /**
139	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
140	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
141	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
142	     *
143	     * @param city the city of the owner being created
144	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
145	     */
146	    private void rejectCityAtCapacity(String city) {
147	        String cityValue = city == null ? "" : city;
148	        long count = this.clinicService.findAllOwners().stream()
149	            .filter(existing -> cityValue.equalsIgnoreCase(
150	                existing.getCity() == null ? "" : existing.getCity()))
151	            .count();
152	        if (count >= CITY_CAPACITY) {
153	            throw new CityAtCapacityException(city);
154	        }
155	    }
156	
157	    /**
158	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
159	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
160	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
161	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
162	     *
163	     * @param city the owner's city
164	     * @param lastName the owner's last name
165	     * @return the assigned customer code
166	     */
167	    private String assignCustomerCode(String city, String lastName) {
168	        String city3 = prefix3(city);
169	        String last3 = prefix3(lastName);
170	        String cityValue = city == null ? "" : city;
171	        int sequence = (int) this.clinicService.findAllOwners().stream()
172	            .filter(existing -> cityValue.equalsIgnoreCase(
173	                existing.getCity() == null ? "" : existing.getCity()))
174	            .count() + 1;
175	        return String.format("%s-%s-%04d", city3, last3, sequence);
176	    }
177	
178	    /**
179	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
180	     * shorter, treating {@code null} as empty.
181	     */
182	    private String prefix3(String value) {
183	        String name = value == null ? "" : value;
184	        return name.substring(0, Math.min(3, name.length()))
185	            .toUpperCase(java.util.Locale.ROOT);
186	    }
187	
188	    /**
189	     * Counts how many existing owners share the given first and last name, compared
190	     * case-insensitively, at the time this owner is created. The value excludes the owner
191	     * being created (which has not yet been saved) and is stored on the new owner and returned
192	     * as its {@code namesakeCount}.
193	     *
194	     * @param firstName the first name of the owner being created
195	     * @param lastName the last name of the owner being created
196	     * @return the number of existing owners with the same first and last name
197	     */
198	    private int countNamesakes(String firstName, String lastName) {
199	        String first = firstName == null ? "" : firstName;
200	        String last = lastName == null ? "" : lastName;
201	        return (int) this.clinicService.findAllOwners().stream()
202	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
203	                && last.equalsIgnoreCase(existing.getLastName()))
204	            .count();
205	    }
206	
207	    /**
208	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
209	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
210	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
211	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
212	     * {@code "+61412345678"}. The E.164 value is stored and returned.
213	     *
214	     * @param telephone the raw telephone as submitted
215	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
216	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
217	     */
218	    private String normalizeTelephone(String telephone) {
219	        String raw = telephone == null ? "" : telephone.trim();
220	        boolean hasCountryCode = raw.startsWith("+");
221	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
222	        if (hasCountryCode) {
223	            cleaned = cleaned.substring(1);
224	        }
225	        String digits;
226	        if (hasCountryCode) {
227	            digits = cleaned;
228	        } else {
229	            if (cleaned.startsWith("0")) {
230	                cleaned = cleaned.substring(1);
231	            }
232	            digits = "61" + cleaned;
233	        }
234	        if (!digits.matches("[0-9]{8,15}")) {
235	            throw new InvalidTelephoneException(telephone);
236	        }
237	        return "+" + digits;
238	    }
239	
240	    /**
241	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
242	     * multi-character top-level label. Deliberately lenient about the exact character set while still
243	     * rejecting values that are clearly not addresses (e.g. missing '@').
244	     */
245	    private static final java.util.regex.Pattern EMAIL_PATTERN =
246	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
247	
248	    /**
249	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
250	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
251	     * lower-cased before being stored and returned.
252	     *
253	     * @param email the raw email as submitted, may be {@code null}
254	     * @return the lower-cased email, or {@code null} when none was supplied
255	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
256	     */
257	    private String normalizeEmail(String email) {
258	        if (email == null || email.isBlank()) {
259	            return null;
260	        }
261	        String trimmed = email.trim();
262	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
263	            throw new InvalidEmailException(email);
264	        }
265	        return trimmed.toLowerCase(java.util.Locale.ROOT);
266	    }
267	
268	    /**
269	     * Common street-type abbreviations expanded to their full word during address normalization.
270	     */
271	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
272	        "ST", "STREET",
273	        "RD", "ROAD",
274	        "AVE", "AVENUE");
275	
276	    /**
277	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
278	     * whitespace collapse to a single space, the value is upper-cased and common street-type
279	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
280	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
281	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
282	     * for every address comparison (household duplicate detection and the shared household id).
283	     *
284	     * @param address the raw address as submitted
285	     * @return the normalized address
286	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
287	     */
288	    private String normalizeAddress(String address) {
289	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
290	        if (collapsed.isEmpty()) {
291	            throw new InvalidAddressException(address);
292	        }
293	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
294	        StringBuilder normalized = new StringBuilder(collapsed.length());
295	        for (int i = 0; i < tokens.length; i++) {
296	            if (i > 0) {
297	                normalized.append(' ');
298	            }
299	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
300	        }
301	        return normalized.toString();
302	    }
303	
304	    /**
305	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
306	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
307	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
308	     * {@code "+61 412 345 678"}) are still treated as duplicates.
309	     *
310	     * @param telephone the E.164 telephone of the owner being created
311	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
312	     */
313	    private void rejectDuplicateTelephone(String telephone) {
314	        boolean duplicate = this.clinicService.findAllOwners().stream()
315	            .map(Owner::getTelephone)
316	            .filter(existing -> existing != null)
317	            .map(this::toE164OrNull)
318	            .filter(existing -> existing != null)
319	            .anyMatch(telephone::equals);
320	        if (duplicate) {
321	            throw new DuplicateTelephoneException(telephone);
322	        }
323	    }
324	
325	    /**
326	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
327	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
328	     */
329	    private String toE164OrNull(String telephone) {
330	        try {
331	            return normalizeTelephone(telephone);
332	        } catch (InvalidTelephoneException e) {
333	            return null;
334	        }
335	    }
336	
337	    /**
338	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
339	     * already has the same last name and the same address. Last names are compared case-insensitively
340	     * with whitespace collapsed; addresses are compared in their normalized form (see
341	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
342	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
343	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
344	     *
345	     * @param lastName the last name of the owner being created
346	     * @param address the normalized address of the owner being created
347	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
348	     */
349	    private void rejectDuplicateHousehold(String lastName, String address) {
350	        String normalizedLastName = Households.normalize(lastName);
351	        String normalizedAddress = Households.normalize(address);
352	        boolean duplicate = this.clinicService.findAllOwners().stream()
353	            .anyMatch(existing ->
354	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
355	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
356	        if (duplicate) {
357	            throw new DuplicateHouseholdException(lastName, address);
358	        }
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
364	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
365	        if (currentOwner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        currentOwner.setAddress(ownerFieldsDto.getAddress());
369	        currentOwner.setCity(ownerFieldsDto.getCity());
370	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
371	        currentOwner.setLastName(ownerFieldsDto.getLastName());
372	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
373	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
374	        this.clinicService.saveOwner(currentOwner);
375	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
376	    }
377	
378	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
379	    @Transactional
380	    @Override
381	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
382	        Owner owner = this.clinicService.findOwnerById(ownerId);
383	        if (owner == null) {
384	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
385	        }
386	        this.clinicService.deleteOwner(owner);
387	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
388	    }
389	
390	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
391	    @Override
392	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
393	        Owner owner = this.clinicService.findOwnerById(ownerId);
394	        if (owner == null) {
395	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
396	        }
397	        HttpHeaders headers = new HttpHeaders();
398	        Pet pet = petMapper.toPet(petFieldsDto);
399	        owner.setId(ownerId);
400	        pet.setOwner(owner);
401	        pet.getType().setName(null);
402	        this.clinicService.savePet(pet);
403	        PetDto petDto = petMapper.toPetDto(pet);
404	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
405	            .buildAndExpand(pet.getId()).toUri());
406	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
407	    }
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Override
411	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
412	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
413	        if (currentOwner != null) {
414	            Pet currentPet = this.clinicService.findPetById(petId);
415	            if (currentPet != null) {
416	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
417	                currentPet.setName(petFieldsDto.getName());
418	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
419	                this.clinicService.savePet(currentPet);
420	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
421	            }
422	        }
423	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
424	    }
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
429	        HttpHeaders headers = new HttpHeaders();
430	        Visit visit = visitMapper.toVisit(visitFieldsDto);
431	        Pet pet = new Pet();
432	        pet.setId(petId);
433	        visit.setPet(pet);
434	        this.clinicService.saveVisit(visit);
435	        VisitDto visitDto = visitMapper.toVisitDto(visit);
436	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
437	            .buildAndExpand(visit.getId()).toUri());
438	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
439	    }
440	
441	
442	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
443	    @Override
444	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
445	        Owner owner = this.clinicService.findOwnerById(ownerId);
446	        if (owner != null) {
447	            Pet pet = owner.getPet(petId);
448	            if (pet != null) {
449	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
450	            }
451	        }
452	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
453	    }
454	}
