17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	
56	    /**
57	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
58	     * class.
59	     *
60	     * @param e     Object referring to the thrown exception.
61	     * @param status HTTP response status.
62	     * @param url URL request.
63	     */
64	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
65	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
66	        problemDetail.setType(URI.create(url.toString()));
67	        problemDetail.setTitle(e.getClass().getSimpleName());
68	        problemDetail.setDetail(detail);
69	        problemDetail.setProperty("timestamp", Instant.now());
70	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
71	        return problemDetail;
72	    }
73	
74	    /**
75	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
76	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
77	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
78	     * would catch it and report an authorization failure as a 500.
79	     *
80	     * @param e The {@link AccessDeniedException} to propagate
81	     * @throws AccessDeniedException always
82	     */
83	    @ExceptionHandler(AccessDeniedException.class)
84	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
85	        throw e;
86	    }
87	
88	    /**
89	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
90	     *
91	     * @param e The {@link Exception} to be handled
92	     * @param request {@link HttpServletRequest} object referring to the current request.
93	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
94	     */
95	    @ExceptionHandler(Exception.class)
96	    @ResponseBody
97	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
98	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
99	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
100	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
101	        return ResponseEntity.status(status).body(detail);
102	    }
103	
104	    /**
105	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
106	     * method returns a 404 Not Found status if an entity does not exist.
107	     *
108	     * @param e The {@link DataIntegrityViolationException} to be handled
109	     * @param request {@link HttpServletRequest} object referring to the current request.
110	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
111	     */
112	    @ExceptionHandler(DataIntegrityViolationException.class)
113	    @ResponseBody
114	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
115	        logger.warn("Data integrity violation at {} {}: {}",
116	            request.getMethod(),
117	            request.getRequestURI(),
118	            e.getMessage());
119	        logger.debug("Data integrity violation stacktrace", e);
120	        HttpStatus status = HttpStatus.NOT_FOUND;
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles {@link InvalidTelephoneException} thrown while normalizing an owner's telephone on create.
127	     *
128	     * @param e The {@link InvalidTelephoneException} to be handled
129	     * @param request {@link HttpServletRequest} object referring to the current request.
130	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
131	     */
132	    @ExceptionHandler(InvalidTelephoneException.class)
133	    @ResponseBody
134	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
135	        HttpStatus status = HttpStatus.BAD_REQUEST;
136	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
137	        detail.setProperty("errors", List.of("telephone"));
138	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
139	        detail.setProperty("schemaValidationErrors", List.of(
140	            new ValidationMessageDto("Field 'telephone' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
141	                .putAdditionalProperty("field", "telephone")
142	                .putAdditionalProperty("rejectedValue", rejectedValue)
143	                .putAdditionalProperty("defaultMessage", e.getMessage())));
144	        return ResponseEntity.status(status).body(detail);
145	    }
146	
147	    /**
148	     * Handles {@link InvalidEmailException} thrown while normalizing an owner's email on create.
149	     *
150	     * @param e The {@link InvalidEmailException} to be handled
151	     * @param request {@link HttpServletRequest} object referring to the current request.
152	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
153	     */
154	    @ExceptionHandler(InvalidEmailException.class)
155	    @ResponseBody
156	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
157	        HttpStatus status = HttpStatus.BAD_REQUEST;
158	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
159	        detail.setProperty("errors", List.of("email"));
160	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
161	        detail.setProperty("schemaValidationErrors", List.of(
162	            new ValidationMessageDto("Field 'email' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
163	                .putAdditionalProperty("field", "email")
164	                .putAdditionalProperty("rejectedValue", rejectedValue)
165	                .putAdditionalProperty("defaultMessage", e.getMessage())));
166	        return ResponseEntity.status(status).body(detail);
167	    }
168	
169	    /**
170	     * Handles {@link InvalidAddressException} thrown while normalizing an owner's address on create.
171	     *
172	     * @param e The {@link InvalidAddressException} to be handled
173	     * @param request {@link HttpServletRequest} object referring to the current request.
174	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
175	     */
176	    @ExceptionHandler(InvalidAddressException.class)
177	    @ResponseBody
178	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
179	        HttpStatus status = HttpStatus.BAD_REQUEST;
180	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
181	        detail.setProperty("errors", List.of("address"));
182	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
183	        detail.setProperty("schemaValidationErrors", List.of(
184	            new ValidationMessageDto("Field 'address' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
185	                .putAdditionalProperty("field", "address")
186	                .putAdditionalProperty("rejectedValue", rejectedValue)
187	                .putAdditionalProperty("defaultMessage", e.getMessage())));
188	        return ResponseEntity.status(status).body(detail);
189	    }
190	
191	    /**
192	     * Handles {@link DuplicateTelephoneException} thrown when creating an owner whose normalized
193	     * telephone is already used by another owner.
194	     *
195	     * @param e The {@link DuplicateTelephoneException} to be handled
196	     * @param request {@link HttpServletRequest} object referring to the current request.
197	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
198	     */
199	    @ExceptionHandler(DuplicateTelephoneException.class)
200	    @ResponseBody
201	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
202	        HttpStatus status = HttpStatus.CONFLICT;
203	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
204	        detail.setProperty("errors", List.of("telephone"));
205	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
206	        detail.setProperty("schemaValidationErrors", List.of(
207	            new ValidationMessageDto("Field 'telephone' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
208	                .putAdditionalProperty("field", "telephone")
209	                .putAdditionalProperty("rejectedValue", rejectedValue)
210	                .putAdditionalProperty("defaultMessage", e.getMessage())));
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles {@link DuplicateHouseholdException} thrown when creating an owner whose last name and
216	     * address already match another owner (they share a household) without opting in via
217	     * {@code sharesHousehold}.
218	     *
219	     * @param e The {@link DuplicateHouseholdException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
222	     */
223	    @ExceptionHandler(DuplicateHouseholdException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.CONFLICT;
227	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
228	        detail.setProperty("errors", List.of("lastName", "address"));
229	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
230	        detail.setProperty("schemaValidationErrors", List.of(
231	            new ValidationMessageDto("Fields 'lastName' and 'address' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
232	                .putAdditionalProperty("field", "lastName")
233	                .putAdditionalProperty("rejectedValue", rejectedValue)
234	                .putAdditionalProperty("defaultMessage", e.getMessage())));
235	        return ResponseEntity.status(status).body(detail);
236	    }
237	
238	    /**
239	     * Handles {@link CityAtCapacityException} thrown when creating an owner whose city already
240	     * contains the maximum number of owners.
241	     *
242	     * @param e The {@link CityAtCapacityException} to be handled
243	     * @param request {@link HttpServletRequest} object referring to the current request.
244	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
245	     */
246	    @ExceptionHandler(CityAtCapacityException.class)
247	    @ResponseBody
248	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
249	        HttpStatus status = HttpStatus.CONFLICT;
250	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
251	        detail.setProperty("errors", List.of("city"));
252	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
253	        detail.setProperty("schemaValidationErrors", List.of(
254	            new ValidationMessageDto("Field 'city' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
255	                .putAdditionalProperty("field", "city")
256	                .putAdditionalProperty("rejectedValue", rejectedValue)
257	                .putAdditionalProperty("defaultMessage", e.getMessage())));
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles exception thrown by Bean Validation on controller methods parameters
263	     *
264	     * @param e The {@link MethodArgumentNotValidException} to be handled
265	     * @param request {@link HttpServletRequest} object referring to the current request.
266	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
267	     */
268	    @ExceptionHandler(MethodArgumentNotValidException.class)
269	    @ResponseBody
270	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
271	        HttpStatus status = HttpStatus.BAD_REQUEST;
272	        BindingErrorsResponse errors = new BindingErrorsResponse();
273	        BindingResult bindingResult = e.getBindingResult();
274	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
275	        if (bindingResult.hasErrors()) {
276	            errors.addAllErrors(bindingResult);
277	            List<String> errorFields = bindingResult.getFieldErrors().stream()
278	                .map(org.springframework.validation.FieldError::getField)
279	                .distinct()
280	                .toList();
281	            detail.setProperty("errors", errorFields);
282	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
283	                .map(fieldError -> {
284	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
285	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
286	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
287	                        fieldError.getField(),
288	                        defaultMessage,
289	                        rejectedValue);
290	                    return new ValidationMessageDto(message)
291	                        .putAdditionalProperty("field", fieldError.getField())
292	                        .putAdditionalProperty("rejectedValue", rejectedValue)
293	                        .putAdditionalProperty("defaultMessage", defaultMessage);
294	                })
295	                .toList();
296	            logger.debug("Validation error at {} {}: {}",
297	                request.getMethod(),
298	                request.getRequestURI(),
299	                bindingResult.getFieldErrors());
300	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
301	            return ResponseEntity.status(status).body(detail);
302	        }
303	        return ResponseEntity.status(status).body(detail);
304	    }
305	
306	}
